def median(xs):
    values = sorted(xs)
    count = len(values)
    if count == 0:
        raise ValueError("median() needs at least one value")
    middle = count // 2
    if count % 2 == 1:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2
